import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Count opponent cooperation rate with recency weighting
    opp_coops = 0.0
    weight_sum = 0.0
    for i in range(n):
        w = 1.0 + (i / max(1, n - 1)) * 2.5
        weight_sum += w
        if history[i][1] == 'C':
            opp_coops += w
    coop_rate = opp_coops / weight_sum if weight_sum > 0 else 0.5

    # Count our own cooperation rate
    my_coops = sum(1 for h in history if h[0] == 'C')
    my_rate = my_coops / n

    last_opp = history[-1][1]

    # Detect patterns of defection streaks
    streak_defect = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_defect += 1
        else:
            break

    streak_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_coop += 1
        else:
            break

    # Remaining rounds
    remaining = 100 - n

    # Near the end, exploit more aggressively based on opponent tendencies
    if remaining <= 2:
        if coop_rate > 0.65:
            return 'D'
        if coop_rate < 0.35:
            return 'D'
        return 'C'

    if remaining <= 5:
        # Defect if opponent seems cooperative or if we already have advantage
        if coop_rate > 0.55:
            return 'D'
        if last_opp == 'D' and streak_defect >= 2:
            return 'D'
        return 'C' if coop_rate > 0.4 else 'D'

    if remaining <= 12:
        if coop_rate > 0.6:
            return 'D'
        if streak_defect >= 2:
            return 'D'
        if last_opp == 'C' and streak_coop >= 3:
            return 'C'
        return 'D' if coop_rate < 0.3 else 'C'

    # Early-mid game: tit-for-tat-ish with generosity and occasional probing
    if last_opp == 'D':
        if streak_defect >= 3:
            # Retaliate hard
            return 'D'
        if streak_defect == 2:
            # Mostly retaliate
            return 'D' if rng.random() < 0.85 else 'C'
        # Single defection - retaliate but forgive quickly
        return 'D' if rng.random() < 0.7 else 'C'

    # Opponent just cooperated
    if streak_coop >= 1:
        # Reward cooperation, but occasionally probe
        if n > 20 and rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'

